      <Button tone="danger">Action</Button>
      <Text tone="secondary" size="caption" weight="label">soft</Text>
      <Button variant="soft">Action</Button>
      <Button variant="soft" tone="accent">Action</Button>
      <Button variant="soft" tone="danger">Action</Button>
      <Text tone="secondary" size="caption" weight="label">ghost</Text>
      <Button variant="ghost">Action</Button>
      <Button variant="ghost" tone="accent">Action</Button>
      <Button variant="ghost" tone="danger">Action</Button>
      <Text tone="secondary" size="caption" weight="label">translucent</Text>
      <Button variant="translucent">Action</Button>
      <Button variant="translucent" tone="accent">Action</Button>
      <Button variant="translucent" tone="danger">Action</Button>
    </Grid>
  );
}

